function PipelineVCamLock:SetController( controller_ )
    self._controller = controller_
end

---@return void
---@param other_ UnityEngine.Collider
function PipelineVCamLock:OnTriggerEnter(other_)
    self._controller:Lock( other_.gameObject )
end


---@return void
---@param other_ UnityEngine.Collider
function PipelineVCamLock:OnTriggerExit(other_)
    self._controller:Unlock( other_.gameObject )
end





